 void campaign(){work.execute(()->{try{JSONObject ad=api.call("/campaign",null,vault.token());if(!ad.optBoolean("enabled"))return;int revision=ad.optInt("revision");android.content.SharedPreferences seen=getSharedPreferences("campaign",0);if(revision<=seen.getInt("seen",0))return;String link=ad.getString("url");Uri uri=Uri.parse(link);if(!"https".equals(uri.getScheme())||uri.getHost()==null)return;runOnUiThread(()->{if(isFinishing()||!screen.equals("chats"))return;seen.edit().putInt("seen",revision).apply();new AlertDialog.Builder(this).setTitle("Реклама · "+ad.optString("title")).setMessage(ad.optString("text")).setNegativeButton("Закрыть",null).setPositiveButton("Подробнее",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){error("Не удалось открыть браузер");}}).show();});}catch(Exception ignored){/* Optional, never blocks messaging. */}});}
 void renderChats(){if(!screen.equals("chats"))return;content.removeAllViews();try{JSONObject c=vault.copy();JSONObject contacts=c.getJSONObject("contacts");JSONArray messages=c.getJSONArray("messages");List<String> names=new ArrayList<>();contacts.keys().forEachRemaining(names::add);
  names.sort((a,b)->Long.compare(lastTime(messages,b),lastTime(messages,a)));
  if(names.isEmpty()){space(content,24);LinearLayout.LayoutParams m=new LinearLayout.LayoutParams(dp(210),dp(210));m.gravity=Gravity.CENTER_HORIZONTAL;content.addView(new Mascot(this),m);TextView empty=label("Первое «привет» — за тобой",22,TEXT);empty.setGravity(Gravity.CENTER);content.addView(empty);space(content,14);paragraph(content,"Нажми «Новый», найди друга по нику и начни разговор. Другу тоже понадобится OldЫ Chat.");return;}
  for(String n:names){JSONObject u=contacts.getJSONObject(n);LinearLayout item=row();pad(item,14);item.setBackground(shape(CARD,22));TextView av=label(u.optString("name",n).substring(0,1).toUpperCase(Locale.ROOT),22,BG);av.setTypeface(null,1);av.setGravity(Gravity.CENTER);av.setBackground(shape(GREEN,24));item.addView(av,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout detail=col();detail.setPadding(dp(14),0,0,0);TextView name=label(u.optString("name",n),17,TEXT);name.setTypeface(null,1);detail.addView(name);JSONObject last=last(messages,n);TextView preview=label(last==null?"@"+n:last.optString("text"),14,MUTED);preview.setSingleLine(true);preview.setEllipsize(TextUtils.TruncateAt.END);detail.addView(preview);item.addView(detail,new LinearLayout.LayoutParams(0,-2,1));item.addView(label(last==null?"→":clock(last.optLong("time")),11,MUTED));item.setOnClickListener(v->openChat(n));content.addView(item,new LinearLayout.LayoutParams(-1,dp(83)));space(content,10);}
 }catch(Exception e){error(e.getMessage());}}
 JSONObject last(JSONArray a,String n){for(int i=a.length()-1;i>=0;i--){JSONObject m=a.optJSONObject(i);if(m!=null&&m.optString("peer").equals(n))return m;}return null;}
 long lastTime(JSONArray a,String n){JSONObject m=last(a,n);return m==null?0:m.optLong("time");}
 String clock(long t){return new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date(t));}
 void findPeer(){LinearLayout box=col();pad(box,20);EditText query=field(box,"Введите ник друга",false);query.setInputType(145);LinearLayout results=col();box.addView(results);AlertDialog d=new AlertDialog.Builder(this).setTitle("Новый разговор").setView(box).setNegativeButton("Закрыть",null).create();box.addView(button("Найти",true,()->{String q=query.getText().toString().trim().toLowerCase(Locale.ROOT);if(!q.matches("[a-z0-9_]{1,24}")){error("Введите ник латиницей");return;}task(()->{JSONArray users=api.call("/users?q="+q,null,vault.token()).getJSONArray("users");runOnUiThread(()->{results.removeAllViews();if(users.length()==0)results.addView(label("Пока никого. Проверь написание.",14,MUTED));for(int i=0;i<users.length();i++){JSONObject u=users.optJSONObject(i);space(results,8);results.addView(button(u.optString("name")+" · @"+u.optString("nick"),false,()->task(()->{vault.pin(u);runOnUiThread(()->{d.dismiss();openChat(u.optString("nick"));});})));}});});}));d.show();}
